      "title": "Cortex Intelligence Indices",
      "date": "2026-01-01",
      "medium": "Page",
      "excerpt": "Evaluate brand experience, visual design quality, and promotional value through normalized metrics.",
      "description": "Evaluate brand experience, visual design quality, and promotional value through normalized metrics.",
      "author": "Jurnii Research",
      "category": "Competitor",
      "tags": [],
      "icon": "lucide:Zap",
      "order": 10,
      "heroFeatures": [
        {
          "title": "Query",
          "description": "Input prospective budget shifts, affiliate variables, or competitive positioning strategies."
        },
        {
          "title": "Model",
          "description": "Analyze massive competitor campaigns and internal signup volumes via Cortex's causal attribution system."
        },
        {
          "title": "Simulate",
          "description": "Simulate Net Gaming Revenue lift, GGR holds, and player acquisition yields under high market volatility."
        }
      ],
      "pullQuote": "Drive decisions from objective ratings. Cortex indexes hundreds of usability, technical speed, and campaign generosity variables into standardized benchmarks.",
      "pullQuoteAttribution": "Chief Commercial Officer, European Tier-1 Operator",
      "productRefs": [
        "jurnii-360",
        "jurnii-ux"
      ],
      "featureRefs": [],
